  function walk(root) {
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT); let n; const L = [];
    while ((n = w.nextNode())) { const v = n.nodeValue.trim(); if (/^[MTWFS]$/.test(v)) { L.push(n); continue; } if (n.__vi === n.nodeValue || isIcon(n.parentElement)) continue; const t = tr(n.nodeValue); if (t != null && t !== n.nodeValue) n.nodeValue = t; n.__vi = n.nodeValue; }
    for (let i = 0; i + 7 <= L.length; i++) { if (WK.every((c, j) => L[i + j].nodeValue.trim() === c)) { WK.forEach((c, j) => { L[i + j].nodeValue = WV[j]; }); i += 6; } }
    root.querySelectorAll && root.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(i => { const t = tr(i.placeholder); if (t) i.placeholder = t; });
  }
  function watch(root) {
    let q = 0; walk(root);
    const mo = new MutationObserver(() => { if (q) return; q = requestAnimationFrame(() => { q = 0; mo.disconnect(); walk(root); mo.observe(root, opts); }); });
    const opts = { subtree: true, childList: true, characterData: true };
    mo.observe(root, opts); return () => mo.disconnect();
  }
